const mentions = [
  {published_at:'2026-08-25T08:10:00Z',headline:'Why attack-surface visibility is becoming a board topic',source:'Security Ledger',author:'Maya Chen',sentiment:'positive',reach:82000,country:'US',themes:['attack-surface visibility','board-level risk'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-25T12:40:00Z',headline:'AegisLayer adds context to cloud exposure alerts',source:'CloudSec Weekly',author:'Jon Bell',sentiment:'positive',reach:36000,country:'UK',themes:['cloud risk','attack-surface visibility'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-26T09:05:00Z',headline:'Security leaders compare exposure-management platforms',source:'Enterprise IT Review',author:'Priya Nair',sentiment:'neutral',reach:54000,country:'IN',themes:['attack-surface visibility','competitive evaluation'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-27T07:50:00Z',headline:'Practitioners debate alert fatigue in exposure management',source:'Security Forum',author:'community moderator',sentiment:'negative',reach:18000,country:'US',themes:['alert fatigue','cloud risk'],competitor:'AegisLayer',share_of_voice:0.42,risk_signal:'product complexity concern'},
  {published_at:'2026-08-27T14:15:00Z',headline:'Analyst note: exposure management moves toward continuous evidence',source:'Tech Market Brief',author:'Owen Price',sentiment:'positive',reach:67000,country:'US',themes:['analyst validation','attack-surface visibility'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-28T11:30:00Z',headline:'What CISOs want from the next generation of security dashboards',source:'CISO Network',author:'Hana Ibrahim',sentiment:'neutral',reach:41000,country:'AE',themes:['board-level risk','analyst validation'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-30T10:05:00Z',headline:'Continuous exposure evidence enters the CISO vocabulary',source:'The Digital Enterprise',author:'Nadia Rahman',sentiment:'positive',reach:73000,country:'SG',themes:['analyst validation','breach disclosure readiness'],competitor:'AegisLayer',share_of_voice:0.42},
  {published_at:'2026-08-31T09:15:00Z',headline:'The case for evidence-led incident communications',source:'Cyber Risk Today',author:'Maya Chen',sentiment:'positive',reach:61000,country:'US',themes:['breach disclosure readiness','regional adoption'],competitor:'AegisLayer',share_of_voice:0.42}
];
return {json:{source_mode:'DEMO',brand:'AegisLayer (fictional cybersecurity technology company)',period_start:'2026-08-25',period_end:'2026-08-31',previous_period_mention_count:6,competitor_share_of_voice:{AegisLayer:0.42,'Northstar Sentinel':0.31,CloudFence:0.27},mentions}};

const root = $json || {};
const mentions = Array.isArray(root.mentions) ? root.mentions : (Array.isArray(root.data) ? root.data : (Array.isArray(root.results) ? root.results : []));
const unavailable = 'unavailable — field absent or not calculable from supplied data';
const countBy = (values) => values.reduce((a,v)=>{ if(v !== undefined && v !== null && v !== '') a[String(v)] = (a[String(v)]||0)+1; return a; },{});
const top = (obj,n=5) => Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,n).map(([label,count])=>({label,count}));
const sentiment = countBy(mentions.map(m=>String(m.sentiment||'unknown').toLowerCase()));
const sources = countBy(mentions.map(m=>m.source));
const authors = countBy(mentions.map(m=>m.author));
const geographies = countBy(mentions.map(m=>m.country || m.geography));
const themes = countBy(mentions.flatMap(m=>Array.isArray(m.themes)?m.themes:[]));
const previous = Number(root.previous_period_mention_count ?? root.previousPeriodMentionCount);
const total = mentions.length;
const change = Number.isFinite(previous) ? total - previous : null;
const changePct = Number.isFinite(previous) && previous !== 0 ? Math.round((change/previous)*1000)/10 : null;
const dated = mentions.filter(m=>m.published_at || m.publishedAt).sort((a,b)=>new Date(a.published_at||a.publishedAt)-new Date(b.published_at||b.publishedAt));
const split = Math.max(1,Math.floor(dated.length*0.6));
const olderThemes = countBy(dated.slice(0,split).flatMap(m=>Array.isArray(m.themes)?m.themes:[]));
const recentThemes = countBy(dated.slice(split).flatMap(m=>Array.isArray(m.themes)?m.themes:[]));
const emerging = Object.entries(recentThemes).filter(([k,v])=>v > (olderThemes[k]||0)).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([label,recent_count])=>({label,recent_count,previous_count:olderThemes[label]||0}));
const highImpact = mentions.filter(m=>Number.isFinite(Number(m.reach))).sort((a,b)=>Number(b.reach)-Number(a.reach)).slice(0,5).map(m=>({headline:m.headline||unavailable,source:m.source||unavailable,reach:Number(m.reach),sentiment:m.sentiment||unavailable}));
const competitorSov = root.competitor_share_of_voice || root.competitorShareOfVoice || unavailable;
const risks = mentions.filter(m=>String(m.sentiment||'').toLowerCase()==='negative' || m.risk_signal).slice(0,5).map(m=>({signal:m.risk_signal||'negative sentiment',evidence:m.headline||unavailable,source:m.source||unavailable}));
const positiveThemes = top(countBy(mentions.filter(m=>String(m.sentiment||'').toLowerCase()==='positive').flatMap(m=>Array.isArray(m.themes)?m.themes:[])),5);
return {json:{...root,metrics:{total_mentions:total,previous_period_mentions:Number.isFinite(previous)?previous:unavailable,change_in_mentions:change===null?unavailable:change,change_percent:changePct===null?unavailable:changePct+'%',sentiment_distribution:Object.keys(sentiment).length?sentiment:unavailable,major_sources:top(sources),top_narratives:top(themes),emerging_narratives:emerging.length?emerging:unavailable,high_impact_mentions:highImpact.length?highImpact:unavailable,competitor_share_of_voice:competitorSov,notable_authors:top(authors),geographic_signals:top(geographies),unusual_spike:changePct===null?unavailable:(changePct>=50?'possible spike — validate against baseline':'no unusual spike detected'),reputational_risks:risks.length?risks:unavailable,communications_opportunities:positiveThemes.length?positiveThemes:unavailable,evidence:mentions.slice(0,10).map(m=>({headline:m.headline||unavailable,source:m.source||unavailable,sentiment:m.sentiment||unavailable,reach:m.reach??unavailable,themes:m.themes||unavailable}))}}};

const m = $json.metrics;
const evidence = (m.evidence || []).map((e,i)=>({evidence_id:i+1,...e}));
const prompt = ['You are preparing an executive communications brief from supplied media intelligence.','Use only the metrics and evidence below. Do not invent coverage, outlets, reach, sentiment, competitors, events, or causes. If a field is unavailable, write unavailable. Distinguish observed evidence from interpretation.','Return exactly these sections: EXECUTIVE SUMMARY; WHAT HAPPENED; WHAT CHANGED; WHY IT MATTERS; TOP NARRATIVES; REPUTATIONAL RISKS; COMMUNICATIONS OPPORTUNITIES; RECOMMENDED ACTIONS; WATCH NEXT.','Every material assertion must cite one or more evidence_id values in square brackets.','METRICS:',JSON.stringify(m,null,2),'EVIDENCE:',JSON.stringify(evidence,null,2)].join('\n\n');
return {json:{...$json,llm_prompt:prompt,llm_stage:'after deterministic metrics',llm_guardrail:'Evidence only; unavailable when absent; human review required'}};

const m = $json.metrics;
const list = (v) => Array.isArray(v) && v.length ? v.map(x=>typeof x==='string'?x:(x.label||x.headline||JSON.stringify(x))).join('; ') : (v || 'unavailable');
const summary = m.total_mentions==='unavailable' ? 'Mention volume is unavailable from the supplied dataset.' : 'The demo dataset contains '+m.total_mentions+' mentions; volume changed by '+m.change_in_mentions+' ('+m.change_percent+') versus the supplied previous-period baseline.';
const actions = [];
if (m.unusual_spike && String(m.unusual_spike).includes('possible spike')) actions.push('Validate the apparent volume change against the monitoring baseline before changing channel posture.');
if (m.reputational_risks !== 'unavailable') actions.push('Assign an owner to validate each risk signal and prepare approved response options.');
actions.push('Use the highest-reach evidence and emerging narratives to brief spokespeople and content leads.');
actions.push('Keep any external response behind the organisation\'s normal approval process.');
const brief = {EXECUTIVE_SUMMARY:summary,WHAT_HAPPENED:'Observed coverage is represented by the supplied evidence list; no claims beyond that dataset are added.',WHAT_CHANGED:'Mention-volume change: '+m.change_in_mentions+'; percentage change: '+m.change_percent+'; possible spike status: '+m.unusual_spike+'.',WHY_IT_MATTERS:'The signals point to themes that may affect stakeholder attention, trust, or message priorities; validate interpretation with subject-matter owners.',TOP_NARRATIVES:list(m.top_narratives),REPUTATIONAL_RISKS:list(m.reputational_risks),COMMUNICATIONS_OPPORTUNITIES:list(m.communications_opportunities),RECOMMENDED_ACTIONS:actions,WATCH_NEXT:'Watch the emerging narratives, high-impact sources, sentiment mix, competitor share-of-voice, and any new evidence that changes the risk assessment.'};
return {json:{...$json,demo_executive_brief:brief,analysis_mode:'DEMO_DETERMINISTIC_FALLBACK',human_review_required:true}};
